def materialize(s):
    value=deepcopy(base);value["sample_clock"]=s["sample_clock"]
    for t in s["replace_tables"]:value["tables"][t]={}
    for t,rows in s["upsert_records"].items():value["tables"][t].update(deepcopy(rows))
    return value

def inferred(values):
    nonnull=[v for v in values if v is not None]
    if not nonnull:return {"type":["string","null"]}
    types=set("boolean" if isinstance(v,bool) else "integer" if isinstance(v,int) else "number" if isinstance(v,float) else "object" if isinstance(v,dict) else "array" if isinstance(v,list) else "string" for v in nonnull)
    if len(types)>1:return {"anyOf":[inferred([v for v in nonnull if ("boolean" if isinstance(v,bool) else "integer" if isinstance(v,int) else "number" if isinstance(v,float) else "object" if isinstance(v,dict) else "array" if isinstance(v,list) else "string")==t]) for t in sorted(types)]+([{"type":"null"}] if len(nonnull)<len(values) else [])}
    t=next(iter(types));s={"type":[t,"null"] if len(nonnull)<len(values) else t}
    if t=="object":
        keys=set().union(*(v.keys() for v in nonnull));s.update(properties={k:inferred([v.get(k) for v in nonnull]) for k in sorted(keys)},required=sorted(set.intersection(*(set(v) for v in nonnull))),additionalProperties=False)
    elif t=="array":
        flat=[x for v in nonnull for x in v];s["items"]=inferred(flat) if flat else {}
    return s

